-- ============================================
-- ESTADOS: situación del trámite de cada persona. Son los colores de fila
-- del Excel (leyenda): citados, no asistieron, biométricos, no contestan,
-- carnet de extranjería, menores en renuncia, renunciantes.
-- PERSONAS."ID_ESTADO" NULL = sin estado (fila blanca en el Excel).
-- ============================================
CREATE TABLE IF NOT EXISTS "ESTADOS" (
    "ID_ESTADO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_ESTADOS" PRIMARY KEY,
    "NOMBRE" VARCHAR(100) NOT NULL CONSTRAINT "UQ_ESTADOS_NOMBRE" UNIQUE,
    "COLOR" VARCHAR(7) NOT NULL DEFAULT '#94A3B8',
    "ORDEN" INT NOT NULL DEFAULT 50,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
